-- Exact M15 catalog, immutable artifact and narrow-role verification. Included in readonly verify.sql.
DO $feedback_verify$
DECLARE expected record;actual jsonb;role_name text;privilege_name text;allowed text[];fn jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM forge_agent.schema_migrations WHERE version=15 AND name='coding_feedback_loop') THEN RAISE EXCEPTION 'Missing M15 feedback migration';END IF;
 FOR expected IN SELECT 'coding_review_policy'::text AS name,$catalog0${"columns":[["owner_id","text",true,null],["project_alias","text",true,null],["version","text",true,"'forge-repair-v1'::text"],["max_rounds","integer",true,"3"],["max_stagnant_rounds","integer",true,"2"],["max_infrastructure_retries","integer",true,"1"],["required_hosted_checks","text[]",true,"ARRAY['check'::text, 'pr-fast-gate'::text, 'real-browser'::text]"]],"indexes":[["coding_review_policy_pkey","CREATE UNIQUE INDEX coding_review_policy_pkey ON forge_agent.coding_review_policy USING btree (owner_id, project_alias)",true,true]],"triggers":[],"constraints":[["coding_review_policy_max_infrastructure_retries_check","c","CHECK (((max_infrastructure_retries >= 0) AND (max_infrastructure_retries <= 3)))",true,false,false],["coding_review_policy_max_rounds_check","c","CHECK (((max_rounds >= 0) AND (max_rounds <= 10)))",true,false,false],["coding_review_policy_max_stagnant_rounds_check","c","CHECK (((max_stagnant_rounds >= 1) AND (max_stagnant_rounds <= 10)))",true,false,false],["coding_review_policy_pkey","p","PRIMARY KEY (owner_id, project_alias)",true,false,false],["coding_review_policy_required_hosted_checks_check","c","CHECK (((cardinality(required_hosted_checks) >= 1) AND (cardinality(required_hosted_checks) <= 16)))",true,false,false],["coding_review_policy_version_check","c","CHECK ((version = 'forge-repair-v1'::text))",true,false,false]]}$catalog0$::jsonb AS data LOOP
SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,pg_get_constraintdef(x.oid),x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) INTO actual FROM pg_class c WHERE c.oid=('forge_agent.'||expected.name)::regclass AND c.relowner='forge_agent_owner'::regrole;
 IF actual IS DISTINCT FROM expected.data THEN RAISE EXCEPTION 'Feedback schema drift: %',expected.name;END IF;
 END LOOP;
 FOR expected IN SELECT 'coding_reviews'::text AS name,$catalog1${"columns":[["review_id","uuid",true,"gen_random_uuid()"],["owner_id","text",true,null],["project_alias","text",true,null],["task_id","uuid",true,null],["attempt_id","uuid",true,null],["plan_decision_id","uuid",false,null],["reconciliation_receipt_id","uuid",true,null],["base_revision","text",true,null],["workspace_digest","text",true,null],["parent_result_sha256","text",true,null],["source_revision","bigint",true,null],["review_no","integer",true,null],["round","integer",true,"0"],["stagnant_rounds","integer",true,"0"],["infrastructure_retries","integer",true,"0"],["previous_review_id","uuid",false,null],["status","text",true,"'pending'::text"],["worker_id","text",false,null],["lease_token","uuid",false,null],["lease_expires_at","timestamp with time zone",false,null],["candidate_commit","text",false,null],["gate_manifest_sha256","text",false,null],["findings","jsonb",true,"'[]'::jsonb"],["verified_finding_ids","jsonb",true,"'[]'::jsonb"],["verification","jsonb",true,"'{}'::jsonb"],["fingerprint","text",false,null],["summary","text",true,"''::text"],["reason","text",true,"''::text"],["feedback_id","uuid",false,null],["finish_token","uuid",false,null],["finish_receipt","jsonb",false,null],["created_at","timestamp with time zone",true,"clock_timestamp()"],["updated_at","timestamp with time zone",true,"clock_timestamp()"],["owner_decision","jsonb",false,null],["repair_task_id","uuid",false,null]],"indexes":[["coding_reviews_owner_id_project_alias_task_id_review_no_key","CREATE UNIQUE INDEX coding_reviews_owner_id_project_alias_task_id_review_no_key ON forge_agent.coding_reviews USING btree (owner_id, project_alias, task_id, review_no)",true,true],["coding_reviews_pending","CREATE INDEX coding_reviews_pending ON forge_agent.coding_reviews USING btree (owner_id, status, created_at)",true,true],["coding_reviews_pkey","CREATE UNIQUE INDEX coding_reviews_pkey ON forge_agent.coding_reviews USING btree (review_id)",true,true]],"triggers":[],"constraints":[["coding_reviews_base_revision_check","c","CHECK ((base_revision ~ '^[0-9a-f]{40}$'::text))",true,false,false],["coding_reviews_candidate_commit_check","c","CHECK (((candidate_commit IS NULL) OR (candidate_commit ~ '^[0-9a-f]{40}$'::text)))",true,false,false],["coding_reviews_check","c","CHECK (((status = 'checking'::text) = ((lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL))))",true,false,false],["coding_reviews_feedback_fk","f","FOREIGN KEY (feedback_id) REFERENCES forge_agent.coding_feedback(feedback_id)",true,false,false],["coding_reviews_findings_check","c","CHECK (((jsonb_typeof(findings) = 'array'::text) AND (octet_length((findings)::text) <= 65536)))",true,false,false],["coding_reviews_fingerprint_check","c","CHECK (((fingerprint IS NULL) OR (fingerprint ~ '^[0-9a-f]{64}$'::text)))",true,false,false],["coding_reviews_gate_manifest_sha256_check","c","CHECK (((gate_manifest_sha256 IS NULL) OR (gate_manifest_sha256 ~ '^[0-9a-f]{64}$'::text)))",true,false,false],["coding_reviews_infrastructure_retries_check","c","CHECK (((infrastructure_retries >= 0) AND (infrastructure_retries <= 32)))",true,false,false],["coding_reviews_owner_id_project_alias_task_id_attempt_id_fkey","f","FOREIGN KEY (owner_id, project_alias, task_id, attempt_id) REFERENCES forge_agent.coding_attempts(owner_id, project_alias, task_id, attempt_id)",true,false,false],["coding_reviews_owner_id_project_alias_task_id_review_no_key","u","UNIQUE (owner_id, project_alias, task_id, review_no)",true,false,false],["coding_reviews_parent_result_sha256_check","c","CHECK ((parent_result_sha256 ~ '^[0-9a-f]{64}$'::text))",true,false,false],["coding_reviews_pkey","p","PRIMARY KEY (review_id)",true,false,false],["coding_reviews_previous_review_id_fkey","f","FOREIGN KEY (previous_review_id) REFERENCES forge_agent.coding_reviews(review_id)",true,false,false],["coding_reviews_reason_check","c","CHECK ((octet_length(reason) <= 4096))",true,false,false],["coding_reviews_reconciliation_receipt_id_fkey","f","FOREIGN KEY (reconciliation_receipt_id) REFERENCES forge_agent.coding_reconciliation_receipts(receipt_id)",true,false,false],["coding_reviews_review_no_check","c","CHECK ((review_no > 0))",true,false,false],["coding_reviews_round_check","c","CHECK (((round >= 0) AND (round <= 32)))",true,false,false],["coding_reviews_source_revision_check","c","CHECK (((source_revision >= 1) AND (source_revision <= '9007199254740990'::bigint)))",true,false,false],["coding_reviews_stagnant_rounds_check","c","CHECK (((stagnant_rounds >= 0) AND (stagnant_rounds <= 32)))",true,false,false],["coding_reviews_status_check","c","CHECK ((status = ANY (ARRAY['pending'::text, 'checking'::text, 'approved'::text, 'repair'::text, 'retry_infrastructure'::text, 'awaiting_review'::text, 'handoff'::text, 'cancelled'::text, 'needs_reconcile'::text, 'revise_plan'::text])))",true,false,false],["coding_reviews_summary_check","c","CHECK ((octet_length(summary) <= 4096))",true,false,false],["coding_reviews_verification_check","c","CHECK (((jsonb_typeof(verification) = 'object'::text) AND (octet_length((verification)::text) <= 65536)))",true,false,false],["coding_reviews_verified_finding_ids_check","c","CHECK ((jsonb_typeof(verified_finding_ids) = 'array'::text))",true,false,false],["coding_reviews_workspace_digest_check","c","CHECK ((workspace_digest ~ '^[0-9a-f]{64}$'::text))",true,false,false]]}$catalog1$::jsonb AS data LOOP
SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,pg_get_constraintdef(x.oid),x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) INTO actual FROM pg_class c WHERE c.oid=('forge_agent.'||expected.name)::regclass AND c.relowner='forge_agent_owner'::regrole;
