 END LOOP;
 FOR expected IN SELECT 'coding_feedback'::text AS name,$catalog2${"columns":[["feedback_id","uuid",true,null],["owner_id","text",true,null],["project_alias","text",true,null],["task_id","uuid",true,null],["parent_attempt_id","uuid",true,null],["review_id","uuid",false,null],["feedback_json","text",true,null],["feedback_sha256","text",true,null],["created_at","timestamp with time zone",true,"clock_timestamp()"]],"indexes":[["coding_feedback_pkey","CREATE UNIQUE INDEX coding_feedback_pkey ON forge_agent.coding_feedback USING btree (feedback_id)",true,true]],"triggers":[["coding_feedback_immutable","CREATE TRIGGER coding_feedback_immutable BEFORE DELETE OR UPDATE ON forge_agent.coding_feedback FOR EACH ROW EXECUTE FUNCTION forge_agent.coding_immutable_record()","O"]],"constraints":[["coding_feedback_check","c","CHECK ((feedback_sha256 = encode(sha256(convert_to(feedback_json, 'UTF8'::name)), 'hex'::text)))",true,false,false],["coding_feedback_feedback_json_check","c","CHECK ((((octet_length(feedback_json) >= 2) AND (octet_length(feedback_json) <= 65536)) AND (jsonb_typeof((feedback_json)::jsonb) = 'object'::text)))",true,false,false],["coding_feedback_owner_id_project_alias_task_id_fkey","f","FOREIGN KEY (owner_id, project_alias, task_id) REFERENCES forge_agent.coding_tasks(owner_id, project_alias, id)",true,false,false],["coding_feedback_parent_attempt_id_fkey","f","FOREIGN KEY (parent_attempt_id) REFERENCES forge_agent.coding_attempts(attempt_id)",true,false,false],["coding_feedback_pkey","p","PRIMARY KEY (feedback_id)",true,false,false],["coding_feedback_review_id_fkey","f","FOREIGN KEY (review_id) REFERENCES forge_agent.coding_reviews(review_id)",true,false,false]]}$catalog2$::jsonb AS data LOOP
