 END LOOP;
 FOR expected IN SELECT 'coding_hosted_checks'::text AS name,$catalog3${"columns":[["observation_id","uuid",true,"gen_random_uuid()"],["owner_id","text",true,null],["project_alias","text",true,null],["task_id","uuid",true,null],["publication_id","uuid",true,null],["candidate_commit","text",true,null],["checks","jsonb",true,null],["required_green","boolean",true,null],["observed_at","timestamp with time zone",true,"clock_timestamp()"]],"indexes":[["coding_hosted_checks_pkey","CREATE UNIQUE INDEX coding_hosted_checks_pkey ON forge_agent.coding_hosted_checks USING btree (observation_id)",true,true]],"triggers":[["coding_hosted_checks_immutable","CREATE TRIGGER coding_hosted_checks_immutable BEFORE DELETE OR UPDATE ON forge_agent.coding_hosted_checks FOR EACH ROW EXECUTE FUNCTION forge_agent.coding_immutable_record()","O"]],"constraints":[["coding_hosted_checks_candidate_commit_check","c","CHECK ((candidate_commit ~ '^[0-9a-f]{40}$'::text))",true,false,false],["coding_hosted_checks_checks_check","c","CHECK (((jsonb_typeof(checks) = 'array'::text) AND (octet_length((checks)::text) <= 65536)))",true,false,false],["coding_hosted_checks_owner_id_project_alias_task_id_fkey","f","FOREIGN KEY (owner_id, project_alias, task_id) REFERENCES forge_agent.coding_tasks(owner_id, project_alias, id)",true,false,false],["coding_hosted_checks_pkey","p","PRIMARY KEY (observation_id)",true,false,false],["coding_hosted_checks_publication_id_fkey","f","FOREIGN KEY (publication_id) REFERENCES forge_agent.coding_publications(publication_id)",true,false,false]]}$catalog3$::jsonb AS data LOOP
